entries.answer:
toml
entrypoint = "file-1.nim"
compile = "mkdir -p bin && nim c -d:release -d:ssl --threads:on --mm:orc --opt:speed --passC:-O3 --passC:-fno-omit-frame-pointer --out:bin/agent-runtime file-1.nim"
run = ["./bin/agent-runtime"]

[nix]
channel = "stable-24_05"

[agent]
expertMode = true

[gitHubImport]
requiredFiles = [".replit", "replit.nix", "file-1.nim"]

[deployment]
build = "mkdir -p bin && nim c -d:release -d:ssl --threads:on --mm:orc --opt:speed --passC:-O3 --passC:-fno-omit-frame-pointer --out:bin/agent-runtime file-1.nim"
run = ["./bin/agent-runtime"]
deploymentTarget = "cloudrun"
ignorePorts = false

[[ports]]
localPort = 8080
externalPort = 80


nix
{ pkgs }: {
  deps = [
    pkgs.nim
    pkgs.gcc
    pkgs.binutils
    pkgs.gnumake
    pkgs.pkg-config
    pkgs.sqlite
    pkgs.openssl
    pkgs.cacert
    pkgs.git
    pkgs.python3
    pkgs.bash
    pkgs.coreutils
    pkgs.findutils
    pkgs.curl
  ];

  env = {
    LD_LIBRARY_PATH = pkgs.lib.makeLibraryPath [
      pkgs.sqlite
      pkgs.openssl
    ];
    LIBRARY_PATH = pkgs.lib.makeLibraryPath [
      pkgs.sqlite
      pkgs.openssl
    ];
    CPATH = pkgs.lib.makeSearchPath "include" [
      pkgs.sqlite
      pkgs.openssl
    ];
    SSL_CERT_FILE = "${pkgs.cacert}/etc/ssl/certs/ca-bundle.crt";
    NIX_SSL_CERT_FILE = "${pkgs.cacert}/etc/ssl/certs/ca-bundle.crt";
    AGENT_DB_PATH = "data/agent-runtime.db";
    AGENT_WORKSPACE = "workspace";
    AGENT_KNOWLEDGE = "knowledge";
    AGENT_PROMPTS_FILE = "config/prompts.yaml";
    AGENT_REFERENCE_SKILLS = "skills";
    AGENT_PUBLIC_ROOT = "public";
    PORT = "8080";
  };
}
